// Appendix B experiment: the machine code that subtracts two doubles.
//
// To see the machine code generated by the JIT, run it in Release with two environment variables.
//
// PowerShell:
//   $env:DOTNET_JitDisasm = "*Subtract* *Folded*"; $env:DOTNET_TieredCompilation = "0"
//   dotnet run -c Release --project experiments/SubtractionInCpu
//
// bash:
//   DOTNET_JitDisasm="*Subtract* *Folded*" DOTNET_TieredCompilation=0 dotnet run -c Release --project experiments/SubtractionInCpu
//
// DOTNET_JitDisasm prints the machine code of the methods whose name matches.
// DOTNET_TieredCompilation=0 makes the JIT produce the optimized code straight away,
// instead of a quick unoptimized version first, so each method is printed only once.

using System.Globalization;
using System.Runtime.CompilerServices;
using Algorithms.Appendix;

CultureInfo.CurrentCulture = CultureInfo.InvariantCulture;

Console.WriteLine($"Subtract(1250.30, 430.20) = {Subtract(1250.30, 430.20)}");
Console.WriteLine($"Folded()                  = {Folded()}");
Console.WriteLine();

// The same subtraction, bit by bit, as the processor does it
var trace = SubtractionTrace.Of(1250.30, 430.20);
Console.WriteLine($"Aligned (× 2^{trace.AlignedExponent}):");
Console.WriteLine($"  {trace.MinuendAligned}   1250.30");
Console.WriteLine($"- {trace.SubtrahendAligned}   430.20");
Console.WriteLine($"= {trace.ExactDifference}");
Console.WriteLine();
Console.WriteLine($"Normalized (× 2^{trace.NormalizedExponent}):");
Console.WriteLine($"  {trace.Normalized}");
Console.WriteLine($"  52 bits that fit: {trace.FittingFraction}");
Console.WriteLine($"  bits left over:   {trace.LeftoverBits}");
Console.WriteLine();

var result = Subtract(1250.30, 430.20);
Console.WriteLine($"Result bits: 0x{BitConverter.DoubleToInt64Bits(result):X16}   exact value {DoubleInspector.ExactValue(result)}");
Console.WriteLine($"820.10 bits: 0x{BitConverter.DoubleToInt64Bits(820.10):X16}   exact value {DoubleInspector.ExactValue(820.10)}");

// NoInlining stops the JIT from copying the method into its caller, so it can be seen on its own
[MethodImpl(MethodImplOptions.NoInlining)]
static double Subtract(double total, double invoice) => total - invoice;

// Two constants: the C# compiler computes the result at build time
[MethodImpl(MethodImplOptions.NoInlining)]
static double Folded() => 1250.30 - 430.20;
